/** 绿茵视界公共及社区模块；本人负责，AI辅助编写。 */ use yii\helpers\Html;$this->title='社区内容审核'; ?><h1>社区内容审核</h1><div class="actions tabs"><?= Html::a('话题审核',['index','kind'=>'post'],['class'=>$kind==='post'?'button':'button secondary']) ?><?= Html::a('评论与回复',['index','kind'=>'comment'],['class'=>$kind==='comment'?'button':'button secondary']) ?></div><table><tr><th>编号</th><th>作者</th><th>内容</th><th>状态</th><th>操作</th></tr><?php foreach($provider->models as $m): ?><tr><td><?= (int)$m->id ?></td><td><?= Html::encode($m->author->username) ?></td><td><?= Html::encode($kind==='post'?$m->title:mb_substr($m->content,0,120)) ?></td><td><?= Html::encode(['pending'=>'待审核','published'=>'已公开','rejected'=>'已驳回','archived'=>'已撤下'][$m->status]) ?></td><td><?= Html::a('审核',['update','id'=>$m->id,'kind'=>$kind]) ?></td></tr><?php endforeach ?></table><?= \yii\widgets\LinkPager::widget(['pagination'=>$provider->pagination]) ?>
